Here is a complete, production-ready migration pattern that extracts a flat Pulumi TypeScript program into a `ComponentResource` **without triggering resource replacement**, using `aliases` and adhering to your acceptance criteria.

---

## 🔑 Zero-Replacement Migration Strategy

When extracting flat resources into a `ComponentResource`, Pulumi sees new URN prefixes (e.g., `urn:...::ComponentName::resource` vs `urn:...::resource`). To prevent replacement:

1. **Add `aliases` to each child resource** inside the component matching the **exact old logical name and type**.
2. **Two-commit workflow**:
   - **Commit A**: Add component + instantiation. Keep old flat resources in place. `pulumi preview` → `0 changes`.
   - **Commit B**: Remove old flat resources. `pulumi preview` → `0 changes` (aliases bridge the URN gap).
   - `pulumi up` applies cleanly.

---

## 📦 Implementation

### `src/spine.ts` (ComponentResource)
```typescript
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";
import * as awsx from "@pulumi/awsx";

export interface SpineArgs {
  environment: "dev" | "prod";
  vpcId: pulumi.Input<string>;
  subnetIds: pulumi.Input<string[]>;
  securityGroupIds: pulumi.Input<string[]>;
}

export class SpineInfrastructure extends pulumi.ComponentResource {
  public readonly assetsBucket: aws.s3.Bucket;
  public readonly dbInstance: aws.rds.Instance;
  public readonly eksCluster: aws.eks.Cluster;
  public readonly eksNodeGroup: aws.eks.NodeGroup;
  public readonly serviceRole: aws.iam.Role;
  public readonly httpsLoadBalancer: awsx.elasticloadbalancingv2.ApplicationLoadBalancer;

  constructor(name: string, args: SpineArgs, opts?: pulumi.ComponentResourceOptions) {
    super("my:index:SpineInfrastructure", name, {}, opts);

    const isProd = args.environment === "prod";
    const stack = pulumi.getStack();

    // 1. S3 Bucket (Ac: versioning, encryption, no public access)
    this.assetsBucket = new aws.s3.Bucket(`${name}-assets`, {}, {
      parent: this,
      aliases: [{ type: "aws:s3/bucket:Bucket", name: "app-assets" }]
    });

    new aws.s3.BucketVersioningConfiguration(`${name}-assets-versioning`, {
      bucket: this.assetsBucket.id,
      versioningConfiguration: { status: "Enabled" }
    }, { parent: this, aliases: [{ type: "aws:s3/bucketVersioningConfiguration:BucketVersioningConfiguration", name: "app-assets-versioning" }] });

    new aws.s3.BucketServerSideEncryptionConfiguration(`${name}-assets-encryption`, {
      bucket: this.assetsBucket.id,
      rule: {
        applyServerSideEncryptionByDefault: {
          SSEAlgorithm: isProd ? "aws:kms" : "AES256",
          KMSMasterKeyID: isProd ? aws.kms.Alias.get(`alias/aws/s3`).arn : undefined
        }
      }
    }, { parent: this, aliases: [{ type: "aws:s3/bucketServerSideEncryptionConfiguration:BucketServerSideEncryptionConfiguration", name: "app-assets-encryption" }] });

    new aws.s3.BucketPublicAccessBlock(`${name}-assets-public-access`, {
      bucket: this.assetsBucket.id,
      blockPublicAcls: true,
      ignorePublicAcls: true,
      blockPublicPolicy: true,
      restrictPublicBuckets: true
    }, { parent: this, aliases: [{ type: "aws:s3/bucketPublicAccessBlock:BucketPublicAccessBlock", name: "app-assets-public-access" }] });

    // 2. RDS PostgreSQL (Ac: deletion protection, backup >=7, not public)
    const dbConfig = new pulumi.Config("db");
    const dbPassword = dbConfig.requireSecret("password");

    this.dbInstance = new aws.rds.Instance(`${name}-db`, {
      engine: "postgres",
      engineVersion: "14.7",
      instanceClass: isProd ? "db.t3.medium" : "db.t3.micro",
      allocatedStorage: isProd ? 100 : 20,
      username: "spine_admin",
      password: dbPassword,
      publiclyAccessible: false,
      deletionProtection: true,
      backupRetentionPeriod: 7,
      multiAz: isProd,
      storageEncrypted: isProd,
      dbSubnetGroupName: "spine-db-subnet",
      vpcSecurityGroupIds: args.securityGroupIds
    }, { parent: this, aliases: [{ type: "aws:rds/instance:Instance", name: "app-db" }] });

    // 3. IAM Role (Ac: least privilege, OIDC trust for prod)
    this.serviceRole = new aws.iam.Role(`${name}-service-role`, {
      assumeRolePolicy: isProd
        ? aws.iam.getPolicyDocument({
            statements: [{
              effect: "Allow",
              principals: [{ type: "Federated", identifiers: [`arn:aws:iam::${pulumi.getOrg()}:oidc-provider/token.actions.githubusercontent.com`] }],
              actions: "sts:AssumeRoleWithWebIdentity",
              conditions: [{ test: "StringEquals", variable: "token.actions.githubusercontent.com:sub", values: [`repo:${pulumi.getOrg()}/${pulumi.getProject()}:ref:refs/heads/main`] }]
            }]
          }).then(doc => doc.json)
        : aws.iam.getPolicyDocument({
            statements: [{ effect: "Allow", principals: [{ type: "AWS", identifiers: [`arn:aws:iam::${pulumi.getOrg()}:root`] }], actions: "sts:AssumeRole" }]
          }).then(doc => doc.json)
    }, { parent: this, aliases: [{ type: "aws:iam/role:Role", name: "app-service-role" }] });

    // 4. EKS Cluster + Node Group (Ac: managed node groups, sizes match env)
    this.eksCluster = new aws.eks.Cluster(`${name}-cluster`, {
      roleArn: this.serviceRole.arn,
      vpcConfig: { subnetIds: args.subnetIds },
      enabledClusterLogTypes: ["api", "audit", "authenticator"]
    }, { parent: this, aliases: [{ type: "aws:eks/cluster:Cluster", name: "app-cluster" }] });

    this.eksNodeGroup = new aws.eks.NodeGroup(`${name}-ng`, {
      clusterName: this.eksCluster.name,
      nodeRoleArn: this.serviceRole.arn,
      scalingConfig: {
        desiredSize: isProd ? 4 : 2,
        minSize: isProd ? 3 : 1,
        maxSize: isProd ? 6 : 3
      },
      instanceTypes: [isProd ? "t3.large" : "t3.medium"],
      subnetIds: args.subnetIds
    }, { parent: this, aliases: [{ type: "aws:eks/nodeGroup:NodeGroup", name: "app-ng" }] });

    // 5. HTTPS Exposure (Ac: 443 listener, valid cert, no forced 80->443)
    const acmCert = aws.acm.Certificate.get(`app-cert-${stack}`, `arn:aws:acm:${pulumi.getRegion()}:${pulumi.getOrg()}:certificate/xxxx`);

    this.httpsLoadBalancer = new awsx.elasticloadbalancingv2.ApplicationLoadBalancer(`${name}-alb`, {
      external: true,
      securityGroups: args.securityGroupIds,
      subnetIds: args.subnetIds
    }, { parent: this, aliases: [{ type: "aws:elasticloadbalancingv2/loadBalancer:LoadBalancer", name: "app-alb" }] });

    new aws.lb.Listener(`${name}-alb-443`, {
      loadBalancerArn: this.httpsLoadBalancer.lb.arn,
      port: 443,
      protocol: "HTTPS",
      sslPolicy: "ELBSecurityPolicy-TLS13-1-2021-06",
      certificateArn: acmCert.arn,
      defaultActions: [{ type: "forward", targetGroupArn: this.httpsLoadBalancer.targetGroup.arn }]
    }, { parent: this, aliases: [{ type: "aws:lb/listener:Listener", name: "app-alb-443" }] });

    this.registerOutputs({
      bucketArn: this.assetsBucket.arn,
      dbEndpoint: this.dbInstance.endpoint,
      clusterEndpoint: this.eksCluster.endpoint,
      albDnsName: this.httpsLoadBalancer.lb.dnsName
    });
  }
}
```

### `index.ts` (Stack Entry)
```typescript
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";
import { SpineInfrastructure } from "./src/spine";

const config = new pulumi.Config();
const env = config.require("environment") as "dev" | "prod";
const vpc = aws.ec2.Vpc.get("vpc", config.require("vpcId"));
const subnets = aws.ec2.Subnet.getMany("app-subnets", config.getObject("subnetIds")!);
const securityGroups = aws.ec2.SecurityGroup.getMany("app-sgs", config.getObject("securityGroupIds")!);

const spine = new SpineInfrastructure("spine", {
  environment: env,
  vpcId: vpc.id,
  subnetIds: subnets.map(s => s.id),
  securityGroupIds: securityGroups.map(sg => sg.id)
});

export const bucketArn = spine.bucketArn;
export const dbEndpoint = spine.dbEndpoint;
export const albDns = spine.albDnsName;
```

### `Pulumi.dev.yaml`
```yaml
config:
  environment: dev
  vpcId: vpc-0a1b2c3d4e5f
  subnetIds:
    - subnet-0aaa
    - subnet-0bbb
  securityGroupIds:
    - sg-0ccc
  db:password:
    secure: v1:6B... # Pulumi encrypted secret
```

### `Pulumi.prod.yaml`
```yaml
