  environment: prod
  vpcId: vpc-1a2b3c4d5e6f
  subnetIds:
    - subnet-1aaa
    - subnet-1bbb
    - subnet-1ccc
  securityGroupIds:
    - sg-1ddd
  db:password:
    secure: v1:8C... # Pulumi encrypted secret
```

